CREATE DATABASE IF NOT EXISTS colibrip_compras CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE colibrip_compras;
CREATE TABLE IF NOT EXISTS usuarios(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,rol ENUM('admin','usuario') NOT NULL DEFAULT 'usuario',activo TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS proveedores(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(180) NOT NULL,rfc VARCHAR(20),telefono VARCHAR(50),email VARCHAR(190),sitio_web VARCHAR(255),notas TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS productos(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(100),no_identificacion VARCHAR(100),nombre VARCHAR(255) NOT NULL,descripcion TEXT,categoria VARCHAR(120),unidad VARCHAR(50),marca VARCHAR(120),costo_actual DECIMAL(12,4) DEFAULT 0,precio_venta DECIMAL(12,4) DEFAULT 0,stock DECIMAL(12,3) DEFAULT 0,min_stock DECIMAL(12,3) DEFAULT 0,activo TINYINT(1) DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(sku),INDEX(no_identificacion));
CREATE TABLE IF NOT EXISTS compras(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,proveedor_id INT UNSIGNED,uuid VARCHAR(36) UNIQUE,serie VARCHAR(30),folio VARCHAR(50),fecha_emision DATETIME,fecha_recepcion DATETIME DEFAULT CURRENT_TIMESTAMP,rfc_emisor VARCHAR(20),rfc_receptor VARCHAR(20),regimen_emisor VARCHAR(20),metodo_pago VARCHAR(10),forma_pago VARCHAR(10),moneda VARCHAR(10),tipo_cambio DECIMAL(18,6) DEFAULT 1,subtotal DECIMAL(14,2) DEFAULT 0,iva DECIMAL(14,2) DEFAULT 0,total DECIMAL(14,2) DEFAULT 0,estado ENUM('pendiente','parcial','pagada','cancelada') DEFAULT 'pendiente',xml_path VARCHAR(500),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(proveedor_id) REFERENCES proveedores(id) ON DELETE SET NULL,INDEX(fecha_emision),INDEX(estado));
CREATE TABLE IF NOT EXISTS conceptos(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,compra_id BIGINT UNSIGNED NOT NULL,producto_id INT UNSIGNED,clave_prod_serv VARCHAR(30),no_identificacion VARCHAR(100),descripcion VARCHAR(500),cantidad DECIMAL(14,4) DEFAULT 0,unidad VARCHAR(80),valor_unitario DECIMAL(14,4) DEFAULT 0,importe DECIMAL(14,2) DEFAULT 0,descuento DECIMAL(14,2) DEFAULT 0,iva DECIMAL(14,2) DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(compra_id) REFERENCES compras(id) ON DELETE CASCADE,FOREIGN KEY(producto_id) REFERENCES productos(id) ON DELETE SET NULL,INDEX(no_identificacion));
CREATE TABLE IF NOT EXISTS pagos(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,compra_id BIGINT UNSIGNED,uuid_pago VARCHAR(36),fecha_pago DATETIME,monto DECIMAL(14,2) DEFAULT 0,num_parcialidad VARCHAR(20),saldo_anterior DECIMAL(14,2) DEFAULT 0,saldo_insoluto DECIMAL(14,2) DEFAULT 0,forma_pago VARCHAR(10),moneda VARCHAR(10),xml_path VARCHAR(500),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(compra_id) REFERENCES compras(id) ON DELETE SET NULL,INDEX(uuid_pago),INDEX(fecha_pago));
CREATE TABLE IF NOT EXISTS precios_web(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,proveedor_id INT UNSIGNED,producto_id INT UNSIGNED,sku VARCHAR(100),nombre VARCHAR(255),url VARCHAR(500),precio DECIMAL(14,4),moneda VARCHAR(10) DEFAULT 'MXN',capturado_at DATETIME DEFAULT CURRENT_TIMESTAMP,fuente VARCHAR(100),FOREIGN KEY(proveedor_id) REFERENCES proveedores(id) ON DELETE SET NULL,FOREIGN KEY(producto_id) REFERENCES productos(id) ON DELETE SET NULL,INDEX(sku),INDEX(capturado_at));
CREATE TABLE IF NOT EXISTS cotizaciones_proveedor(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,proveedor_id INT UNSIGNED,producto_id INT UNSIGNED,nombre_producto VARCHAR(255),sku VARCHAR(100),precio DECIMAL(14,4),unidad VARCHAR(50),vigencia DATE,archivo VARCHAR(500),notas TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(proveedor_id) REFERENCES proveedores(id) ON DELETE SET NULL,FOREIGN KEY(producto_id) REFERENCES productos(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS evaluaciones_calidad(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,producto_id INT UNSIGNED NOT NULL,trabajo_id BIGINT UNSIGNED NULL,adhesion DECIMAL(4,2),secado DECIMAL(4,2),acabado DECIMAL(4,2),durabilidad DECIMAL(4,2),rendimiento DECIMAL(4,2),calidad_precio DECIMAL(4,2),comentarios TEXT,usuario_id INT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(producto_id) REFERENCES productos(id) ON DELETE CASCADE,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS trabajos(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,folio VARCHAR(50),akaunting_contact_id BIGINT UNSIGNED NULL,cliente VARCHAR(180),descripcion VARCHAR(500),estado ENUM('cotizacion','produccion','terminado','entregado') DEFAULT 'cotizacion',precio_venta DECIMAL(14,2) DEFAULT 0,mano_obra DECIMAL(14,2) DEFAULT 0,otros_costos DECIMAL(14,2) DEFAULT 0,fecha DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX idx_trabajos_akaunting_contact (akaunting_contact_id));
CREATE TABLE IF NOT EXISTS trabajos_folios(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trabajo_materiales(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,trabajo_id BIGINT UNSIGNED NOT NULL,producto_id INT UNSIGNED NOT NULL,cantidad DECIMAL(14,4),costo_unitario DECIMAL(14,4),desperdicio_pct DECIMAL(6,2) DEFAULT 0,costo_total DECIMAL(14,2),FOREIGN KEY(trabajo_id) REFERENCES trabajos(id) ON DELETE CASCADE,FOREIGN KEY(producto_id) REFERENCES productos(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS alertas(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tipo VARCHAR(50),titulo VARCHAR(255),mensaje TEXT,nivel ENUM('info','warning','danger','success') DEFAULT 'info',leida TINYINT(1) DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED,accion VARCHAR(100),detalle TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL);

